import { sortBy } from "remeda";
import {
  isNamed,
  parseSource,
  walk,
} from "@/server/features/publishing/metadataSyntax";

// RFC-0011 5.4: the two generated files, and the check of the final pull
// request before approval. Parsing reads syntax only; nothing executes.
const DIRECTORY = "relay-split";

export type SplitFile = { path: string; source: string };

export function splitFiles(
  testId: string,
  variantPaths: string[],
  rootDirectory: string,
): SplitFile[] {
  const directory = [rootDirectory.replace(/\/+$/, ""), DIRECTORY]
    .filter(Boolean)
    .join("/");
  const paths = sortBy(variantPaths, (path) => path);
  return [
    {
      path: `${directory}/${testId}.json`,
      source: `${JSON.stringify({ testId, paths }, null, 2)}\n`,
    },
    {
      path: `${directory}/index.ts`,
      source: `// Generated by Relay for split test ${testId}. It reads a static list and
// no request data, so search engines always see the same version of a page.
import variants from "./${testId}.json";

const paths = new Set<string>(variants.paths);

export function inSplitVariant(path: string): boolean {
  return paths.has(path);
}
`,
    },
  ];
}

type Range = { start: number; end: number };
const inside = (at: Range, list: Range[]) =>
  list.some((range) => at.start >= range.start && at.end <= range.end);

const position = (node: Record<string, unknown>) =>
  typeof node.start === "number" && typeof node.end === "number"
    ? { start: node.start, end: node.end }
    : null;

/** The source ranges of `metadata` and `generateMetadata` exports. */
function metadataRanges(program: ReturnType<typeof parseSource>) {
  const ranges: Array<{ start: number; end: number }> = [];
  for (const statement of program.body) {
    if (statement.type !== "ExportNamedDeclaration" || !statement.declaration)
      continue;
    const declaration = statement.declaration;
    if (
      declaration.type === "FunctionDeclaration" &&
      isNamed(declaration.id, "generateMetadata")
    )
      ranges.push({ start: declaration.start ?? 0, end: declaration.end ?? 0 });
    if (declaration.type === "VariableDeclaration")
      for (const declarator of declaration.declarations)
        if (
          (isNamed(declarator.id, "metadata") ||
            isNamed(declarator.id, "generateMetadata")) &&
          declarator.init
        )
          ranges.push({
            start: declarator.init.start ?? 0,
            end: declarator.init.end ?? 0,
          });
  }
  return ranges;
}

/**
 * The problems with a final pull request; empty when it passes. Only the two
 * generated files and the template change, the variant list matches the
 * stored assignment, and the template uses `inSplitVariant` only inside its
 * metadata.
 */
export function diffCheck(input: {
  changedFiles: string[];
  expected: SplitFile[];
  headJson: string | null;
  template: SplitFile | null;
  templatePath: string;
}) {
  const problems: string[] = [];
  const allowed = new Set([
    ...input.expected.map((file) => file.path),
    input.templatePath,
  ]);
  for (const file of input.changedFiles)
    if (!allowed.has(file))
      problems.push(
        `The pull request also changes ${file}. Only the split files and the template may change.`,
      );
  for (const file of input.expected)
    if (!input.changedFiles.includes(file.path))
      problems.push(`The pull request no longer adds ${file.path}.`);
  const [json] = input.expected;
  if (input.headJson?.trim() !== json?.source.trim())
    problems.push(`${json?.path} differs from the stored assignment.`);
  if (!input.template || !input.changedFiles.includes(input.templatePath)) {
    problems.push(
      `Edit ${input.templatePath} in this pull request, as the description shows.`,
    );
    return problems;
  }
  if (!/(^|\/)app\/(.*\/)?page\.(tsx|ts|jsx|js)$/.test(input.templatePath)) {
    problems.push("Relay checks App Router page templates only.");
    return problems;
  }
  let program: ReturnType<typeof parseSource>;
  try {
    program = parseSource(input.template.source, input.templatePath);
  } catch {
    problems.push(`${input.templatePath} could not be parsed.`);
    return problems;
  }
  const local = program.body
    .flatMap((statement) =>
      statement.type === "ImportDeclaration" &&
      /(^|\/)relay-split(\/index(\.ts)?)?$/.test(statement.source.value)
        ? statement.specifiers
        : [],
    )
    .find(
      (specifier) =>
        specifier.type === "ImportSpecifier" &&
        isNamed(specifier.imported, "inSplitVariant"),
    )?.local.name;
  if (!local) {
    problems.push(`${input.templatePath} does not import inSplitVariant.`);
    return problems;
  }
  const ranges = metadataRanges(program);
  const imports = program.body.flatMap((statement) =>
    statement.type === "ImportDeclaration"
      ? [{ start: statement.start ?? 0, end: statement.end ?? 0 }]
      : [],
  );
  let calls = 0;
  walk(program, (node) => {
    if (node.type === "CallExpression" && isNamed(node.callee, local)) calls++;
    if (!isNamed(node, local)) return;
    const at = position(node);
    if (at && inside(at, imports)) return;
    if (!at || !inside(at, ranges))
      problems.push(
        `${input.templatePath} uses inSplitVariant outside its metadata.`,
      );
  });
  if (!calls)
    problems.push(`${input.templatePath} never calls inSplitVariant.`);
  return [...new Set(problems)];
}
